namespace OcrAcl.Application.Models;

/// <summary>
/// Internal representation of an OCR job as returned by the OCR service.
/// Matches OCR-SRC §3.2 response DTOs.
/// </summary>
public sealed record OcrJob
{
    /// <summary>
    /// OCR-generated job identifier (UUID v4 lowercase).
    /// </summary>
    public required Guid JobId { get; init; }

    /// <summary>
    /// Opaque reference generated by the ACL (≤ 64 chars, [a-z0-9_-]).
    /// Only identifier sent to the OCR service (C-13).
    /// </summary>
    public required string ClientReference { get; init; }

    /// <summary>
    /// Job status: pending, processing, completed, failed.
    /// </summary>
    public required OcrStatus Status { get; init; }

    /// <summary>
    /// Job creation timestamp (ISO 8601 UTC).
    /// </summary>
    public required DateTimeOffset CreatedAt { get; init; }

    /// <summary>
    /// Job completion timestamp (null while running).
    /// </summary>
    public DateTimeOffset? CompletedAt { get; init; }

    /// <summary>
    /// Result payload when status is Completed.
    /// </summary>
    public OcrResult? Result { get; init; }

    /// <summary>
    /// Error payload when status is Failed.
    /// </summary>
    public OcrJobError? Error { get; init; }

    /// <summary>
    /// Polling URL from the OCR service Location header (used for background polling).
    /// </summary>
    public string? PollingUrl { get; init; }
}

/// <summary>
/// Error payload from a failed OCR job (OCR-SRC §3.2).
/// </summary>
public sealed record OcrJobError
{
    /// <summary>
    /// OCR error code (e.g., PASSWORD_PROTECTED_PDF, CORRUPT_DOCUMENT, PROCESSING_TIMEOUT, ENGINE_ERROR).
    /// </summary>
    public required string Code { get; init; }

    /// <summary>
    /// Human-readable error message.
    /// </summary>
    public required string Message { get; init; }
}